export fn pattern_matching(v:[*c]const i64,n:usize)i64{if(v==null or n<3 or n>130 or v[0]<0 or v[0]>64)return -1;const t:usize=@intCast(v[0]);const pp=t+1;if(n<pp+1 or v[pp]<1 or v[pp]>64)return -1;const p:usize=@intCast(v[pp]);if(n!=pp+p+1 or p>t)return -1;for(1..pp)|i|if(v[i]<0 or v[i]>127)return -1;for(pp+1..n)|i|if(v[i]<0 or v[i]>127)return -1;for(0..t-p+1)|i|{var j:usize=0;while(j<p and v[i+1+j]==v[pp+1+j]){j+=1;}if(j==p)return @intCast(i);}return -1;}
